<?php
namespace App\Models;
use App\Models\Concerns\InvalidatesCapabilities; use Illuminate\Database\Eloquent\{Builder,Factories\HasFactory,Model}; use Illuminate\Database\Eloquent\Relations\{BelongsTo,BelongsToMany,HasMany};
class Capability extends Model { use HasFactory, InvalidatesCapabilities; protected $fillable=['capability_category_id','title','slug','eyebrow','short_description','overview','icon','featured_image_path','featured_image_alt','template','hero_style','status','is_featured','display_order','published_at','scheduled_for','archived_at','primary_cta_label','primary_cta_url','secondary_cta_label','secondary_cta_url','meta_title','meta_description','canonical_url','og_title','og_description','og_image_path','robots_index','robots_follow','created_by','updated_by']; protected function casts():array{return ['is_featured'=>'boolean','robots_index'=>'boolean','robots_follow'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];} public function category():BelongsTo{return $this->belongsTo(CapabilityCategory::class,'capability_category_id');} public function highlights():HasMany{return $this->hasMany(CapabilityHighlight::class)->orderBy('display_order');} public function benefits():HasMany{return $this->hasMany(CapabilityBenefit::class)->orderBy('display_order');} public function facts():HasMany{return $this->hasMany(CapabilityFact::class)->orderBy('display_order');} public function relatedSolutions():BelongsToMany{return $this->belongsToMany(Solution::class,'capability_solution_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedProducts():BelongsToMany{return $this->belongsToMany(Product::class,'capability_product_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedIndustries():BelongsToMany{return $this->belongsToMany(Industry::class,'capability_industry_relations')->withPivot('display_order')->orderByPivot('display_order');} public function relatedPages():BelongsToMany{return $this->belongsToMany(Page::class,'capability_page_relations')->withPivot('display_order')->orderByPivot('display_order');} public function navigationItems():HasMany{return $this->hasMany(NavigationItem::class);} public function homepageItems():HasMany{return $this->hasMany(HomepageItem::class);} public function industryNeeds():HasMany{return $this->hasMany(IndustryNeed::class);} public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->whereNotNull('short_description')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));} public function isPubliclyVisible():bool{return $this->archived_at===null&&trim((string)$this->short_description)!==''&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
